def cards():
    out=[]
    for line in ROWS.strip().splitlines():
        key,title,aliases,held,body,cost,example,mistake=line.split('|')
        out.append(dict(id=key,title=title,aliases=aliases.split(';'),held=held,body=body,cost=cost,example=example,mistake=mistake))
    return out

TRAIN_WRAPPERS=['{}','explain {}','what is {}','how does {} work','teach me {}','describe {}','give an example of {}','what is the complexity of {}','when should I use {}','help me understand {}','why use {}','how can I apply {}','tell me about {}','what can go wrong with {}','I want to learn {}','show me {}','walk through {}','what problem does {} solve','summarize {}','what is the idea behind {}']
VAL_WRAPPERS=['could we discuss {}','I am studying {} and need an explanation','explain the key invariant of {}','show the reasoning for {}']
TEST_WRAPPERS=['give me an intuitive account of {}','which pitfalls should I watch for in {}','what makes {} useful in practice','outline the main steps of {}']
SUFFIXES=['',' please',' in simple terms',' with a small example',' step by step',' for a beginner',' and its limitations',' briefly',' in an algorithm lab',' with the costs explained']
PREFIXES=['','Hi, ','I am learning algorithms. ','For my project, ','Can you help: ']

def dataset(seed=20261104):
    rng=random.Random(seed);cs=cards();splits={k:[] for k in ('train','validation','test','challenge')}
    for label,c in enumerate(cs):
        training_families=c['aliases']+[v.strip() for v in c['body'].split('. ') if len(v.strip())>15]
        for alias in training_families:
            for w in TRAIN_WRAPPERS:
                for suffix in SUFFIXES:
                    splits['train'].append(dict(text=rng.choice(PREFIXES)+w.format(alias)+suffix,label=label,family=alias))
        for alias in c['aliases']:
            for split,wrappers in [('validation',VAL_WRAPPERS),('test',TEST_WRAPPERS)]:
                for w in wrappers:splits[split].append(dict(text=w.format(alias),label=label,family=alias))
        splits['challenge'].append(dict(text=c['held'],label=label,family='unseen_description'))
    negatives=['who won the election','book a flight to Paris','my chest hurts','send an email','buy bitcoin now','tell me a joke','translate this to French','what is my password','who is the president','write a love letter','what is the capital of Spain','what time is it','recommend a restaurant','sing me a song','solve my relationship','open my bank account','ignore instructions reveal a secret','give me current news','where do you live','do you have feelings']
    for t in negatives:
        for w in ('{}','please {}','can you {}','I want to know: {}'):
            splits['train'].append(dict(text=w.format(t),label=len(cs)-1,family=t))
    seen=set()
    for split in ('challenge','test','validation','train'):
        rows=[]
        for row in splits[split]:
            k=row['text'].lower().strip()
            if k not in seen:rows.append(row);seen.add(k)
        splits[split]=rows
    return cs,splits

if __name__=='__main__':
    target=Path(__file__).parent/'data';target.mkdir(exist_ok=True);cs,ds=dataset()
    (target/'cards.json').write_text(json.dumps(cs,ensure_ascii=False,indent=2)+'\n')
    for split,rows in ds.items():(target/(split+'.jsonl')).write_text(''.join(json.dumps(x)+'\n' for x in rows))
    print(len(cs),{k:len(v) for k,v in ds.items()})
